.app-wrapper {
  width: 100vw;
  height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #050505;
  overflow: hidden;
}

.cabinet-outer {
  position: relative;
  width: min(95vw, 55vh);
  height: min(168vw, 95vh);
  border-radius: 20px;
  background: #0f1218;
  padding: 2.5vmin;
  box-shadow:
    -8px -8px 24px rgba(255, 255, 255, 0.02),
    8px 8px 36px rgba(0, 0, 0, 0.95),
    inset 0 0 30px rgba(0, 0, 0, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.01);
  display: flex;
  flex-direction: column;
  overflow: visible;
  box-sizing: border-box;
  transition: all 0.2s ease-in-out;
}

.viewport-container {
  width: 100%;
  height: 100%;
  position: relative;
  border: 2px solid rgb(22, 22, 26);
  background: rgb(5, 5, 6);
  overflow: hidden;
  border-radius: 12px;
  box-shadow: inset 0 0 20px rgba(0, 0, 0, 0.8);
  display: flex;
  flex-direction: column;
}

.vignette-overlay {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle, transparent 60%, rgba(0, 0, 0, 0.6) 100%);
  pointer-events: none;
  z-index: 80;
  transition: opacity 0.3s ease;
}

/* Places the telemetry root exactly 44px to the left of the cabinet's bezel */
#debug-telemetry-root {
  position: absolute;
  right: calc(100% + 44px);
  top: 2.5vmin;
  width: 250px;
  z-index: 100;
}

/* Override inline styles generated by DebugTelemetryOverlay.ts class */
#debug-telemetry-root > div {
  position: relative !important;
  top: 0 !important;
  left: 0 !important;
  right: auto !important;
  width: 100% !important;
  margin: 0 !important;
}

/* Hides diagnostic details when displayed space is limited */
@media (max-width: 1000px) {
  #debug-telemetry-root {
    display: none !important;
  }
}

@media (max-width: 768px) and (pointer: coarse) {
  .cabinet-outer {
    width: 100vw !important;
    height: 100vh !important;
    max-width: none !important;
    max-height: none !important;
    border-radius: 0 !important;
    padding: 10px !important;
    box-shadow: none !important;
    border: none !important;
    overflow: hidden !important;
  }

  .viewport-container {
    border-radius: 8px;
  }
}

