import { Engine } from "../core/engine/Engine";
import { EventBroker } from "../core/events/EventBroker";
import { SystemManager } from "../core/systems/SystemManager";
import { CommandBus } from "../core/commands/CommandBus";
import { EcsWorld } from "../core/ecs/EcsWorld";
import { ComponentStore } from "../core/ecs/ComponentStore";
import { EntityRefs } from "../core/ecs/EntityRefs";
import { StoreContainer } from "../core/ecs/StoreContainer";
import { SystemContext } from "../core/engine/SystemContext";
import {
  TransformComponent,
  KinematicVelocityComponent,
  KinematicTargetComponent,
  TetherComponent,
  HealthComponent,
  InputIntentComponent,
  WeaverAIComponent,
  PlayerTag,
  WeaverTag,
  TraversalStateComponent,
  InvulnerabilityComponent,
  WeaverTraversalComponent
} from "../core/ecs/Components";
import { RenderSystem } from "../visual/scene/RenderSystem";
import { VisualRegistry } from "../visual/scene/VisualRegistry";
import { CameraSystem } from "../visual/cameras/CameraSystem";
import { LightingSystem } from "../visual/lighting/LightingSystem";
import { AudioDirectorSystem } from "../audio/systems/AudioDirectorSystem";
import { HudSyncSystem } from "../ui/hud/HudSyncSystem";
import { EntitySpawnerSystem } from "../gameplay/EntitySpawnerSystem";
import { PlayerInputSystem } from "../gameplay/player/PlayerInputSystem";
import { WeaverBrainSystem } from "../gameplay/weaver/WeaverBrainSystem";
import { WeaverTraversalSystem } from "../gameplay/weaver/WeaverTraversalSystem";
import { TetherVisualizerSystem } from "../gameplay/juice/TetherVisualizerSystem";
import { PlayerKinematicsSystem } from "../gameplay/player/PlayerKinematicsSystem";
import { PlayerAnimationSystem } from "../gameplay/player/PlayerAnimationSystem";
import { VerticalBoundarySystem } from "../gameplay/player/VerticalBoundarySystem";
import { HavokPhysicsSystem } from "../physics/havok/HavokPhysicsSystem";
import { ParallaxScrollSystem } from "../visual/systems/ParallaxScrollSystem";
import { EntityInterpolationSystem } from "../visual/systems/EntityInterpolationSystem";
import { VisualStateDressingSystem } from "../visual/systems/VisualStateDressingSystem";
import { CombatSystem } from "../gameplay/combat/CombatSystem";
import { HealthSystem } from "../gameplay/combat/HealthSystem";
import { GameDirectorSystem } from "../gameplay/combat/GameDirectorSystem";
import { ProjectileSystem } from "../gameplay/combat/ProjectileSystem";
import { JuiceSystem } from "../gameplay/juice/JuiceSystem";
import { WeaverShatterSystem } from "../gameplay/juice/WeaverShatterSystem";
import { Profiler } from "../core/diagnostics/Profiler";
import { DebugTelemetryOverlay } from "../core/diagnostics/DebugTelemetryOverlay";
import { PerformanceClock } from "../core/clock/PerformanceClock";
import { RafScheduler } from "../core/loop/RafScheduler";

export class CompositionRoot {
  public buildEngine(canvas: HTMLCanvasElement): Engine {
    const broker = new EventBroker();
    const commands = new CommandBus();
    const profiler = new Profiler();
    const systemManager = new SystemManager(profiler);

    const world = new EcsWorld();
    const transforms = new ComponentStore<TransformComponent>();
    const velocities = new ComponentStore<KinematicVelocityComponent>();
    const targets = new ComponentStore<KinematicTargetComponent>();
    const tethers = new ComponentStore<TetherComponent>();
    const healths = new ComponentStore<HealthComponent>();
    const inputs = new ComponentStore<InputIntentComponent>();
    const weaverAIs = new ComponentStore<WeaverAIComponent>();
    const traversal = new ComponentStore<TraversalStateComponent>();
    const iframes = new ComponentStore<InvulnerabilityComponent>();
    const weaverTraversal = new ComponentStore<WeaverTraversalComponent>();

    const playerTags = new ComponentStore<PlayerTag>();
    const weaverTags = new ComponentStore<WeaverTag>();
    const refs = new EntityRefs(playerTags, weaverTags);

    world.registerStore(transforms);
    world.registerStore(velocities);
    world.registerStore(targets);
    world.registerStore(tethers);
    world.registerStore(healths);
    world.registerStore(inputs);
    world.registerStore(weaverAIs);
    world.registerStore(traversal);
    world.registerStore(iframes);
    world.registerStore(weaverTraversal);
    world.registerStore(playerTags);
    world.registerStore(weaverTags);

    const storeContainer = new StoreContainer();
    storeContainer.register("transform", transforms);
    storeContainer.register("velocity", velocities);
    storeContainer.register("target", targets);
    storeContainer.register("tether", tethers);
    storeContainer.register("health", healths);
    storeContainer.register("input", inputs);
    storeContainer.register("weaverAI", weaverAIs);
    storeContainer.register("traversal", traversal);
    storeContainer.register("iframe", iframes);
    storeContainer.register("weaverTraversal", weaverTraversal);
    storeContainer.register("playerTag", playerTags);
    storeContainer.register("weaverTag", weaverTags);

    const visualRegistry = new VisualRegistry();

    const context = new SystemContext(
      world,
      broker,
      commands,
      refs,
      visualRegistry,
      storeContainer
    );

    const renderSystem = new RenderSystem(canvas, visualRegistry, broker);
    const cameraSystem = new CameraSystem(context);
    const lightingSystem = new LightingSystem(context);
    const tetherVisualizer = new TetherVisualizerSystem(context);
    const juiceSystem = new JuiceSystem(context);
    const shatterSystem = new WeaverShatterSystem(context);
    const audioSystem = new AudioDirectorSystem(context);

    const physicsSystem = new HavokPhysicsSystem(context);

    const playerKinematics = new PlayerKinematicsSystem(context);
    const playerAnimation = new PlayerAnimationSystem(context);
    const environmentCollision = new VerticalBoundarySystem(context);

    const parallaxScroll = new ParallaxScrollSystem(context);
    const interpolationSystem = new EntityInterpolationSystem(context);

    const dressingSystem = new VisualStateDressingSystem(context);
    const inputSystem = new PlayerInputSystem(context);
    const spawner = new EntitySpawnerSystem(context);

    const weaverBrain = new WeaverBrainSystem(context);
    const weaverTraversalSystem = new WeaverTraversalSystem(context);

    const combatSystem = new CombatSystem(context);
    const healthSystem = new HealthSystem(context);
    const projectileSystem = new ProjectileSystem(context);
    const gameDirector = new GameDirectorSystem(context, spawner);

    const hudSystem = new HudSyncSystem(broker);

    const debugTelemetry = new DebugTelemetryOverlay(profiler, context);

    systemManager.register(spawner);
    systemManager.register(renderSystem);
    systemManager.register(physicsSystem);
    systemManager.register(inputSystem);
    systemManager.register(weaverBrain);
    systemManager.register(playerKinematics);
    systemManager.register(playerAnimation);
    systemManager.register(weaverTraversalSystem);
    systemManager.register(environmentCollision);
    systemManager.register(parallaxScroll);
    systemManager.register(interpolationSystem);
    systemManager.register(dressingSystem);
    systemManager.register(tetherVisualizer);
    systemManager.register(cameraSystem);
    systemManager.register(combatSystem);
    systemManager.register(healthSystem);
    systemManager.register(projectileSystem);
    systemManager.register(juiceSystem);
    systemManager.register(shatterSystem);
    systemManager.register(gameDirector);
    systemManager.register(audioSystem);
    systemManager.register(lightingSystem);
    systemManager.register(hudSystem);
    systemManager.register(debugTelemetry);

    const clock = new PerformanceClock();
    const scheduler = new RafScheduler();

    return new Engine(canvas, broker, systemManager, clock, scheduler);
  }
}

src/audio/systems/AudioDirectorSystem.ts:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { EventBroker } from "../../core/events/EventBroker";
import { GameEvent } from "../../core/events/GameEvents";
import { TensionSynthesizer } from "../tone/TensionSynthesizer";
import { AUDIO_PRESETS } from "../tone/AudioPresets";
import { SystemContext } from "../../core/engine/SystemContext";
import { TransformComponent, TraversalStateComponent } from "../../core/ecs/Components";
import { GAMEPLAY_TUNING } from "../../core/engine/ArenaConfig";
import type { MembraneSynth, NoiseSynth, Synth, Panner } from "tone";

export class AudioDirectorSystem implements ISystem {
  readonly phase = SystemPhase.RenderSync;
  private tensionSynth: TensionSynthesizer | null = null;
  private impactSynth: MembraneSynth | null = null;
  private noiseSynth: NoiseSynth | null = null;
  private tickSynth: Synth | null = null;
  private confirmSynth: Synth | null = null;
  private tensionAlarmSynth: Synth | null = null;
  private sfxPanner: Panner | null = null;
  private windowTickListener: (() => void) | null = null;
  private windowConfirmListener: (() => void) | null = null;
  private windowTensionAlarmListener: (() => void) | null = null;
  private initialized: boolean = false;

  private broker: EventBroker;
  private subscriptions: (() => void)[] = [];
  private gestureTriggerRef: (() => void) | null = null;

  private hitComboCount = 0;
  private lastHitTime = 0;
  private toneModule: typeof import("tone") | null = null;

  constructor(private context: SystemContext) {
    this.broker = this.context.broker;

    this.gestureTriggerRef = (): void => {
      this.bootAudioEngine();
      this.removeGestureListeners();
    };

    window.addEventListener("click", this.gestureTriggerRef);
    window.addEventListener("keydown", this.gestureTriggerRef);
    window.addEventListener("touchend", this.gestureTriggerRef);
    window.addEventListener("mousedown", this.gestureTriggerRef);

    this.windowTickListener = () => {
      if (this.initialized && this.tickSynth) {
        this.tickSynth.triggerAttackRelease("E6", "32n");
      }
    };
    window.addEventListener("silk-stats-tick", this.windowTickListener);

    this.windowConfirmListener = () => {
      if (this.initialized && this.confirmSynth) {
        this.confirmSynth.triggerAttackRelease("C6", "16n");
      }
    };
    window.addEventListener("silk-play-confirm", this.windowConfirmListener);

    this.windowTensionAlarmListener = () => {
      if (this.initialized && this.tensionAlarmSynth && Math.random() < 0.1) {
        this.tensionAlarmSynth.triggerAttackRelease("F6", "32n");
      }
    };
    window.addEventListener("silk-tension-alarm", this.windowTensionAlarmListener);
  }

  public init(): void {
    this.subscriptions.push(
      this.broker.subscribe(GameEvent.TETHER_TENSION_CHANGE, (payload) => {
        if (this.initialized && this.tensionSynth) {
          this.tensionSynth.updateDronePitch(payload.tension);
        }
      })
    );

    this.subscriptions.push(
      this.broker.subscribe(GameEvent.PLAYER_STATE_CHANGE, (payload) => {
        if (payload.state === "LAUNCHING" && this.initialized) {
          const travStore = this.context.stores.get<TraversalStateComponent>("traversal");
          const pTrav = travStore.get(this.context.refs.player);
          if (pTrav) {
            const reelConfig = GAMEPLAY_TUNING.REEL;
            const power = pTrav.launchPower;

            if (power >= 1.0) {
              if (this.impactSynth) {
                this.impactSynth.triggerAttackRelease("A1", "4n");
              }
              if (this.noiseSynth) {
                this.noiseSynth.triggerAttackRelease("4n");
              }
            } else if (power >= reelConfig.SWEET_SPOT_MIN && power <= reelConfig.SWEET_SPOT_MAX) {
              if (this.tickSynth) {
                this.tickSynth.triggerAttackRelease("G6", "16n");
              }
              if (this.impactSynth) {
                this.impactSynth.triggerAttackRelease("D4", "16n");
              }
            } else {
              if (this.impactSynth) {
                this.impactSynth.triggerAttackRelease("C3", "16n");
              }
            }
          }
        }
      })
    );

    this.subscriptions.push(
      this.broker.subscribe(GameEvent.PLAYER_HEALTH_CHANGED, (payload) => {
        if (this.initialized && this.tensionSynth) {
          this.tensionSynth.setLowHPStatus(payload.hp === 1);
        }
      })
    );

    this.subscriptions.push(
      this.broker.subscribe(GameEvent.PLAYER_DAMAGED, () => {
        const presets = AUDIO_PRESETS.PLAYER;
        if (this.initialized && this.impactSynth) {
          this.impactSynth.triggerAttackRelease(presets.DAMAGED_NOTE, presets.DAMAGED_DURATION);
        }
        if (this.initialized && this.noiseSynth) {
          this.noiseSynth.triggerAttackRelease(presets.DAMAGED_DURATION);
        }
      })
    );

    this.subscriptions.push(
      this.broker.subscribe(GameEvent.WEAVER_DAMAGED, () => {
        if (this.initialized && this.impactSynth) {
          const nowMs = performance.now();
          if (nowMs - this.lastHitTime < 1500) {
            this.hitComboCount++;
          } else {
            this.hitComboCount = 0;
          }
          this.lastHitTime = nowMs;

          const DORIAN_RATIOS = [1.0000, 1.1225, 1.1892, 1.3348, 1.4983, 1.6818, 1.7818, 2.0000];
          const scaleIndex = this.hitComboCount % DORIAN_RATIOS.length;
          const octave = Math.pow(2, Math.floor(this.hitComboCount / DORIAN_RATIOS.length));
          const baseFreq = 164.81; 
          const freq = baseFreq * DORIAN_RATIOS[scaleIndex] * octave;

          this.impactSynth.triggerAttackRelease(freq, "16n");
        }
      })
    );

    this.subscriptions.push(
      this.broker.subscribe(GameEvent.WEAVER_STATE_CHANGE, (payload) => {
        if (this.initialized && this.tensionSynth) {
          this.tensionSynth.handleStateChange(payload.state);
        }
      })
    );

    this.subscriptions.push(
      this.broker.subscribe(GameEvent.GAME_OVER, () => {
        if (this.initialized && this.tensionSynth) {
          this.tensionSynth.fadeOutAndMute();
        }
      })
    );

    this.subscriptions.push(
      this.broker.subscribe(GameEvent.GAME_WIN, () => {
        if (this.initialized && this.tensionSynth) {
          this.tensionSynth.fadeOutAndMute();
        }
      })
    );

    this.subscriptions.push(
      this.broker.subscribe(GameEvent.GAME_RESET, () => {
        if (this.initialized && this.tensionSynth) {
          this.tensionSynth.resetToBaseline();
        }
        this.hitComboCount = 0;
        this.lastHitTime = 0;
      })
    );

    this.subscriptions.push(
      this.broker.subscribe(GameEvent.GAME_PAUSED, (payload) => {
        if (this.initialized && this.tensionSynth && this.toneModule) {
          const rawCtx = this.toneModule.getContext().rawContext as unknown as AudioContext;
          if (payload.isPaused) {
            this.tensionSynth.fadeOutAndMute();
            if (rawCtx && typeof rawCtx.suspend === "function") {
              rawCtx.suspend();
            }
          } else {
            if (rawCtx && typeof rawCtx.resume === "function") {
              rawCtx.resume().then(() => {
                if (this.initialized && this.tensionSynth) {
                  this.tensionSynth.resumeFromPause();
                }
              });
            } else {
              this.tensionSynth.resumeFromPause();
            }
          }
        }
      })
    );

    this.subscriptions.push(
      this.broker.subscribe(GameEvent.WEAVER_DIED, () => {
        if (this.initialized) {
          const presets = AUDIO_PRESETS.WEAVER;
          if (this.impactSynth) {
            this.impactSynth.triggerAttackRelease(
              presets.DEATH_NOTE_1,
              presets.DEATH_NOTE_1_DURATION
            );
            this.impactSynth.triggerAttackRelease(
              presets.DEATH_NOTE_2,
              presets.DEATH_NOTE_2_DURATION,
              presets.DEATH_NOTE_2_DELAY
            );
          }
          if (this.noiseSynth) {
            this.noiseSynth.envelope.decay = presets.DEATH_NOISE_DECAY;
            this.noiseSynth.triggerAttackRelease(presets.DEATH_NOTE_1_DURATION);
            setTimeout(() => {
              if (this.noiseSynth) this.noiseSynth.envelope.decay = presets.NOISE_DECAY;
            }, presets.DEATH_NOISE_RESTORE_DELAY);
          }
        }
      })
    );

    this.subscriptions.push(
      this.broker.subscribe(GameEvent.PLAYER_DIED, () => {
        if (this.initialized) {
          const presets = AUDIO_PRESETS.PLAYER;
          if (this.impactSynth) {
            this.impactSynth.triggerAttackRelease(
              presets.DEATH_NOTE_1,
              presets.DEATH_NOTE_1_DURATION
            );
            this.impactSynth.triggerAttackRelease(
              presets.DEATH_NOTE_2,
              presets.DEATH_NOTE_2_DURATION,
              presets.DEATH_NOTE_2_DELAY
            );
          }
          if (this.noiseSynth) {
            this.noiseSynth.envelope.decay = presets.DEATH_NOISE_DECAY;
            this.noiseSynth.triggerAttackRelease(presets.DEATH_NOTE_1_DURATION);
            setTimeout(() => {
              if (this.noiseSynth) this.noiseSynth.envelope.decay = presets.NOISE_DECAY;
            }, presets.DEATH_NOISE_RESTORE_DELAY);
          }
        }
      })
    );
  }

  public update(): void {
    if (this.initialized) {
      const transforms = this.context.stores.get<TransformComponent>("transform");
      const playerTrans = transforms.get(this.context.refs.player);
      const weaverTrans = transforms.get(this.context.refs.weaver);
      if (playerTrans && weaverTrans) {
        if (this.tensionSynth) {
          this.tensionSynth.updatePositions(playerTrans.x, weaverTrans.x);
        }
        if (this.sfxPanner && this.toneModule) {
          const panVal = Math.max(-15.0, Math.min(15.0, playerTrans.x)) / 15.0 * 0.45;
          this.sfxPanner.pan.setTargetAtTime(panVal, this.toneModule.now(), 0.05);
        }
      }
    }
  }

  private removeGestureListeners(): void {
    if (this.gestureTriggerRef) {
      window.removeEventListener("click", this.gestureTriggerRef);
      window.removeEventListener("keydown", this.gestureTriggerRef);
      window.removeEventListener("touchend", this.gestureTriggerRef);
      window.removeEventListener("mousedown", this.gestureTriggerRef);
      this.gestureTriggerRef = null;
    }
  }

  private bootAudioEngine(): void {
    if (this.initialized) return;
    import("tone").then((Tone) => {
      this.toneModule = Tone;
      Tone.start().then(() => {
        this.initialized = true;

        Tone.getDestination().mute = false;

        this.sfxPanner = new Tone.Panner(0).toDestination();

        this.tensionSynth = new TensionSynthesizer();
        this.tensionSynth.initialize().then(() => {
          this.broker.publish(GameEvent.USER_GESTURE_REGISTERED, undefined);
        });

        this.impactSynth = new Tone.MembraneSynth({
          pitchDecay: 0.05,
          octaves: 4,
          oscillator: { type: "sine" },
          envelope: {
            attack: 0.001,
            decay: 0.2,
            sustain: 0.01,
            release: 0.4,
            attackCurve: "exponential"
          }
        }).connect(this.sfxPanner);

        const presets = AUDIO_PRESETS.PLAYER;

        this.noiseSynth = new Tone.NoiseSynth({
          noise: { type: "pink" },
          envelope: {
            attack: 0.001,
            decay: presets.NOISE_DECAY,
            sustain: 0,
            release: presets.NOISE_DECAY
          }
        }).connect(this.sfxPanner);
        this.noiseSynth.volume.value = presets.NOISE_VOLUME;

        this.tickSynth = new Tone.Synth({
          oscillator: { type: "sine" },
          envelope: {
            attack: 0.002,
            decay: 0.03,
            sustain: 0,
            release: 0.03
          }
        }).toDestination();
        this.tickSynth.volume.value = -14;

        this.confirmSynth = new Tone.Synth({
          oscillator: { type: "triangle" },
          envelope: {
            attack: 0.002,
            decay: 0.12,
            sustain: 0,
            release: 0.08
          }
        }).toDestination();
        this.confirmSynth.volume.value = -6;

        this.tensionAlarmSynth = new Tone.Synth({
          oscillator: { type: "sine" },
          envelope: {
            attack: 0.01,
            decay: 0.1,
            sustain: 0,
            release: 0.05
          }
        }).toDestination();
        this.tensionAlarmSynth.volume.value = -18;
      });
    });
  }

  public dispose(): void {
    this.removeGestureListeners();
    this.subscriptions.forEach((unsub) => unsub());
    this.subscriptions = [];
    if (this.tensionSynth) this.tensionSynth.dispose();
    if (this.impactSynth) this.impactSynth.dispose();
    if (this.noiseSynth) this.noiseSynth.dispose();
    if (this.tickSynth) this.tickSynth.dispose();
    if (this.confirmSynth) this.confirmSynth.dispose();
    if (this.tensionAlarmSynth) this.tensionAlarmSynth.dispose();
    if (this.sfxPanner) this.sfxPanner.dispose();
    if (this.windowTickListener) {
      window.removeEventListener("silk-stats-tick", this.windowTickListener);
    }
    if (this.windowConfirmListener) {
      window.removeEventListener("silk-play-confirm", this.windowConfirmListener);
    }
    if (this.windowTensionAlarmListener) {
      window.removeEventListener("silk-tension-alarm", this.windowTensionAlarmListener);
    }
  }
}

src/audio/tone/TensionSynthesizer.ts:
import { AUDIO_PRESETS } from "./AudioPresets";
import type { FMOscillator, Filter, Gain, LFO, Synth, MembraneSynth, Loop, Panner } from "tone";

export class TensionSynthesizer {
  private fmOsc: FMOscillator | null = null;
  private lowpassFilter: Filter | null = null;
  private gainNode: Gain | null = null;
  private lfo: LFO | null = null;
  private lastTension: number = -999.0;

  private playerPanner: Panner | null = null;
  private weaverPanner: Panner | null = null;

  private ratchetSynth: Synth | null = null;
  private heartbeatSynth: MembraneSynth | null = null;
  private heartbeatLoop: Loop | null = null;

  private lastRatchetTime: number = 0;
  private nextRatchetDelay: number = 0.25;
  private toneModule: typeof import("tone") | null = null;

  public async initialize(): Promise<void> {
    const Tone = await import("tone");
    this.toneModule = Tone;

    const presets = AUDIO_PRESETS.WEAVER;
    const synthConfig = AUDIO_PRESETS.TENSION_SYNTH;

    Tone.getTransport().bpm.value = 130;
    Tone.getTransport().start();

    this.lowpassFilter = new Tone.Filter({
      frequency: 200,
      type: "lowpass",
      Q: 1.5
    }).toDestination();

    this.playerPanner = new Tone.Panner(0).connect(this.lowpassFilter);
    this.weaverPanner = new Tone.Panner(0).connect(this.lowpassFilter);

    this.fmOsc = new Tone.FMOscillator({
      frequency: presets.DRONE_BASE_FREQ,
      type: "sawtooth",
      modulationType: "sine",
      harmonicity: presets.HARMONICITY_NORMAL,
      modulationIndex: synthConfig.DRONE_MOD_INDEX_BASE,
      workspace: undefined
    } as unknown as ConstructorParameters<typeof FMOscillator>[0]);

    this.gainNode = new Tone.Gain(0.0);

    this.lfo = new Tone.LFO({
      frequency: presets.LFO_NORMAL_HZ,
      min: 150,
      max: 280
    });

    this.fmOsc.connect(this.gainNode);
    this.gainNode.connect(this.weaverPanner);
    this.lfo.connect(this.lowpassFilter.frequency);

    this.ratchetSynth = new Tone.Synth({
      oscillator: { type: "triangle" },
      envelope: {
        attack: 0.001,
        decay: 0.015,
        sustain: 0,
        release: 0.015
      }
    }).connect(this.playerPanner);
    this.ratchetSynth.volume.value = synthConfig.RATCHET_VOLUME;

    this.heartbeatSynth = new Tone.MembraneSynth({
      oscillator: { type: "sine" },
      envelope: {
        attack: 0.001,
        decay: 0.18,
        sustain: 0,
        release: 0.12
      }
    }).connect(this.lowpassFilter);
    this.heartbeatSynth.volume.value = synthConfig.HEARTBEAT_VOLUME;

    this.heartbeatLoop = new Tone.Loop((time) => {
      if (this.heartbeatSynth) {
        this.heartbeatSynth.triggerAttackRelease("A1", "8n", time);
        this.heartbeatSynth.triggerAttackRelease("G1", "8n", time + 0.18);
      }
    }, synthConfig.HEARTBEAT_INTERVAL);

    this.lfo.start();
    this.fmOsc.start();
  }

  private getPanFromX(x: number): number {
    const clampedX = Math.max(-15.0, Math.min(15.0, x));
    return (clampedX / 15.0) * 0.45;
  }

  public updatePositions(playerX: number, weaverX: number): void {
    if (this.playerPanner && this.weaverPanner && this.toneModule) {
      const now = this.toneModule.now();
      this.playerPanner.pan.setTargetAtTime(this.getPanFromX(playerX), now, 0.05);
      this.weaverPanner.pan.setTargetAtTime(this.getPanFromX(weaverX), now, 0.05);
    }
  }

  public updateDronePitch(tensionVal: number): void {
    if (!this.fmOsc || !this.gainNode || !this.lowpassFilter || !this.toneModule) return;

    const clampedTension = Math.max(0, Math.min(1.3, tensionVal));

    if (clampedTension > this.lastTension && clampedTension > 0.05) {
      const now = this.toneModule.now();
      if (now > this.lastRatchetTime + this.nextRatchetDelay) {
        this.lastRatchetTime = now;
        this.nextRatchetDelay = Math.max(0.04, 0.28 - clampedTension * 0.2);
        const pitch = 150 + clampedTension * 320;
        this.ratchetSynth?.triggerAttackRelease(pitch, "32n", now);
      }
    }

    if (Math.abs(clampedTension - this.lastTension) < 0.005) {
      return;
    }
    this.lastTension = clampedTension;

    const now = this.toneModule.now();
    const presets = AUDIO_PRESETS.WEAVER;
    const synthConfig = AUDIO_PRESETS.TENSION_SYNTH;

    const targetBaseFreq = presets.DRONE_BASE_FREQ + Math.min(1.0, clampedTension) * presets.DRONE_BASE_FREQ;
    const targetModulationIndex =
      synthConfig.DRONE_MOD_INDEX_BASE + Math.min(1.0, clampedTension) * synthConfig.DRONE_MOD_INDEX_SCALE;
    const targetGain =
      clampedTension > synthConfig.DRONE_GAIN_THRESHOLD
        ? synthConfig.DRONE_MIN_GAIN + Math.min(1.0, clampedTension) * synthConfig.DRONE_MAX_GAIN_ADD
        : 0.0;

    this.fmOsc.frequency.setTargetAtTime(targetBaseFreq, now, synthConfig.DRONE_PITCH_RAMP_TIME);
    this.fmOsc.modulationIndex.setTargetAtTime(
      targetModulationIndex,
      now,
      synthConfig.DRONE_PITCH_RAMP_TIME
    );
    this.gainNode.gain.setTargetAtTime(targetGain, now, synthConfig.DRONE_GAIN_RAMP_TIME);
  }

  public setLowHPStatus(active: boolean): void {
    if (!this.lfo || !this.heartbeatLoop) return;

    const targetMin = active ? 40 : 150;
    const targetMax = active ? 150 : 280;

    this.lfo.min = targetMin;
    this.lfo.max = targetMax;

    if (active) {
      this.heartbeatLoop.start();
    } else {
      this.heartbeatLoop.stop();
    }
  }

  public resumeFromPause(): void {
    if (!this.fmOsc || !this.gainNode || !this.lowpassFilter || !this.toneModule) return;
    const now = this.toneModule.now();
    const synthConfig = AUDIO_PRESETS.TENSION_SYNTH;
    const clampedTension = this.lastTension === -999.0 ? 0.0 : this.lastTension;
    const targetGain =
      clampedTension > synthConfig.DRONE_GAIN_THRESHOLD
        ? synthConfig.DRONE_MIN_GAIN + clampedTension * synthConfig.DRONE_MAX_GAIN_ADD
        : 0.0;
    this.gainNode.gain.setTargetAtTime(targetGain, now, synthConfig.DRONE_GAIN_RAMP_TIME);
  }

  public handleStateChange(state: string): void {
    if (!this.fmOsc || !this.lfo || !this.lowpassFilter || !this.toneModule) return;
    const now = this.toneModule.now();
    const presets = AUDIO_PRESETS.WEAVER;

    if (state.includes("BERSERK")) {
      this.fmOsc.frequency.setTargetAtTime(presets.DRONE_BERSERK_FREQ, now, 0.5);
      this.lfo.frequency.setTargetAtTime(presets.LFO_BERSERK_HZ, now, 0.5);
      this.fmOsc.harmonicity.setTargetAtTime(presets.HARMONICITY_BERSERK, now, 0.5);
    } else if (state === "WEAVER DEFEATED") {
      this.fmOsc.frequency.setTargetAtTime(presets.DRONE_DEFEATED_FREQ, now, 0.5);
      this.lfo.frequency.setTargetAtTime(presets.LFO_DEFEATED_HZ, now, 0.5);
      this.fmOsc.harmonicity.setTargetAtTime(presets.HARMONICITY_DEFEATED, now, 0.5);
    } else {
      this.fmOsc.frequency.setTargetAtTime(presets.DRONE_BASE_FREQ, now, 0.5);
      this.lfo.frequency.setTargetAtTime(presets.LFO_NORMAL_HZ, now, 0.5);
      this.fmOsc.harmonicity.setTargetAtTime(presets.HARMONICITY_NORMAL, now, 0.5);
    }
  }

  public fadeOutAndMute(): void {
    if (!this.gainNode || !this.toneModule) return;
    const now = this.toneModule.now();
    this.gainNode.gain.setTargetAtTime(0.0, now, 0.15);
  }

  public resetToBaseline(): void {
    if (!this.fmOsc || !this.gainNode || !this.lfo || !this.lowpassFilter || !this.toneModule) return;
    const now = this.toneModule.now();
    const presets = AUDIO_PRESETS.WEAVER;

    this.gainNode.gain.setValueAtTime(0.0, now);
    this.fmOsc.frequency.setValueAtTime(presets.DRONE_BASE_FREQ, now);
    this.fmOsc.harmonicity.setValueAtTime(presets.HARMONICITY_NORMAL, now);
    this.lfo.frequency.setValueAtTime(presets.LFO_NORMAL_HZ, now);
    this.setLowHPStatus(false);
  }

  public dispose(): void {
    if (this.fmOsc) {
      this.fmOsc.stop();
      this.fmOsc.dispose();
    }
    if (this.lfo) {
      this.lfo.stop();
      this.lfo.dispose();
    }
    if (this.lowpassFilter) {
      this.lowpassFilter.dispose();
    }
    if (this.gainNode) {
      this.gainNode.dispose();
    }
    if (this.playerPanner) {
      this.playerPanner.dispose();
    }
    if (this.weaverPanner) {
      this.weaverPanner.dispose();
    }
    if (this.ratchetSynth) {
      this.ratchetSynth.dispose();
    }
    if (this.heartbeatSynth) {
      this.heartbeatSynth.dispose();
    }
    if (this.heartbeatLoop) {
      this.heartbeatLoop.dispose();
    }
  }
}

