import { ARENA_CONFIG, GAMEPLAY_TUNING } from "../../core/engine/ArenaConfig";
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import {
  TransformComponent,
  WeaverAIComponent,
  TetherComponent,
  TraversalStateComponent,
  KinematicTargetComponent,
  InvulnerabilityComponent,
  KinematicVelocityComponent
} from "../../core/ecs/Components";
import { SystemContext } from "../../core/engine/SystemContext";
import { GameEvent } from "../../core/events/GameEvents";

export class CombatSystem implements ISystem {
  readonly phase = SystemPhase.Gameplay;
  private readonly COMBINED_RADIUS_THRESHOLD =
    ARENA_CONFIG.ENTITY.PLAYER_RADIUS + ARENA_CONFIG.ENTITY.WEAVER_RADIUS;
  private readonly BROADPHASE_ENVELOPE =
    (ARENA_CONFIG.ENTITY.PLAYER_RADIUS +
      ARENA_CONFIG.ENTITY.WEAVER_RADIUS +
      GAMEPLAY_TUNING.COMBAT.BROADPHASE_MARGIN) *
    (ARENA_CONFIG.ENTITY.PLAYER_RADIUS +
      ARENA_CONFIG.ENTITY.WEAVER_RADIUS +
      GAMEPLAY_TUNING.COMBAT.BROADPHASE_MARGIN);

  constructor(private context: SystemContext) {}

  public update(): void {
    const transforms = this.context.stores.get<TransformComponent>("transform");
    const pTrans = transforms.get(this.context.refs.player);
    const wTrans = transforms.get(this.context.refs.weaver);
    if (!pTrans || !wTrans) return;

    const dx = pTrans.x - wTrans.x;
    const dy = pTrans.y - wTrans.y;
    const distSq = dx * dx + dy * dy;

    if (distSq > this.BROADPHASE_ENVELOPE) return;

    const dist = Math.sqrt(distSq) || 1.0;
    const isColliding = dist < this.COMBINED_RADIUS_THRESHOLD;
    if (!isColliding) return;

    const wAI = this.context.stores
      .get<WeaverAIComponent>("weaverAI")
      .get(this.context.refs.weaver);
    const tether = this.context.stores.get<TetherComponent>("tether").get(this.context.refs.player);
    const pTrav = this.context.stores
      .get<TraversalStateComponent>("traversal")
      .get(this.context.refs.player);
    const pIframe = this.context.stores
      .get<InvulnerabilityComponent>("iframe")
      .get(this.context.refs.player);
    const pVel = this.context.stores
      .get<KinematicVelocityComponent>("velocity")
      .get(this.context.refs.player);

    if (!wAI || !tether || !pTrav || !pIframe || !pVel) return;

    const tuning = GAMEPLAY_TUNING.COMBAT;

    if (pTrav.state === "LAUNCHING" && pTrav.launchPower >= tuning.FLING_DAMAGE_THRESHOLD) {
      this.context.commands.dispatch({
        type: "DAMAGE_REQUEST",
        targetId: this.context.refs.weaver,
        amount: tuning.PLAYER_FLING_DAMAGE,
        source: "PLAYER_FLING"
      });

      this.context.broker.publish(GameEvent.CAMERA_SHAKE_TRIGGERED, {
        amplitude: 1.4,
        duration: 0.55,
        dirX: dx / dist,
        dirY: dy / dist
      });

      pVel.x = (dx / dist) * tuning.REBOUND_FORCE;
      pVel.y = (dy / dist) * tuning.REBOUND_FORCE;
      pTrav.state = "AIRBORNE";
      pTrav.launchPower = 0;
      pTrav.launchTimer = 0;
      return;
    }

    const weaverIsHostile = wAI.state === "STRIKING";
    if (pIframe.timeRemaining <= 0 && weaverIsHostile) {
      const kbX = (dx / dist) * tuning.KNOCKBACK_FORCE_X;
      const kbY = (dy / dist) * tuning.KNOCKBACK_FORCE_Y + tuning.KNOCKBACK_BONUS_Y;

      this.context.commands.dispatch({
        type: "DAMAGE_REQUEST",
        targetId: this.context.refs.player,
        amount: tuning.WEAVER_CONTACT_DAMAGE,
        source: "WEAVER",
        knockbackX: kbX,
        knockbackY: kbY
      });

      this.context.broker.publish(GameEvent.CAMERA_SHAKE_TRIGGERED, {
        amplitude: 0.5,
        duration: 0.3,
        dirX: dx / dist,
        dirY: dy / dist
      });
      return;
    }

    if (dist < this.COMBINED_RADIUS_THRESHOLD) {
      const overlap = this.COMBINED_RADIUS_THRESHOLD - dist;
      const nx = dx / dist;
      const ny = dy / dist;
      const shiftX = nx * overlap;
      const shiftY = ny * overlap;

      pTrans.x += shiftX;
      pTrans.y += shiftY;
      pTrans.prevX += shiftX;
      pTrans.prevY += shiftY;

      const pTarget = this.context.stores
        .get<KinematicTargetComponent>("target")
        .get(this.context.refs.player);
      if (pTarget) {
        pTarget.x += shiftX;
        pTarget.y += shiftY;
      }

      const dot = pVel.x * nx + pVel.y * ny;
      if (dot < 0) {
        pVel.x -= dot * nx * tuning.BOUNCE_ELASTICITY_MULT;
        pVel.y -= dot * ny * tuning.BOUNCE_ELASTICITY_MULT;
      }
    }
  }
}

src/gameplay/combat/GameDirectorSystem.t:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { GameEvent } from "../../core/events/GameEvents";
import { SystemContext } from "../../core/engine/SystemContext";
import { HealthComponent, TetherComponent } from "../../core/ecs/Components";
import { EntitySpawnerSystem } from "../EntitySpawnerSystem";
import { GAMEPLAY_TUNING, VISUAL_JUICE_CONFIG } from "../../core/engine/ArenaConfig";

export class GameDirectorSystem implements ISystem {
  readonly phase = SystemPhase.Gameplay;
  public static timeScale = 1.0;

  private gameState: "PLAYING" | "GAME_OVER" | "VICTORY" = "PLAYING";
  private resetRequested = false;
  private HASH = String.fromCharCode(35);
  private unsubscribes: (() => void)[] = [];

  private activeCinematic: "NONE" | "PLAYER_DEATH" | "WEAVER_DEATH" = "NONE";
  private cinematicTimer = 0.0;
  private maxCinematicSimTime = 0.6;

  private adrenalineTimer = 0.0;
  private readonly ADRENALINE_SURGE_DURATION = 1.2;

  constructor(
    private context: SystemContext,
    private spawner: EntitySpawnerSystem
  ) {}

  public init(): void {
    this.unsubscribes.push(
      this.context.broker.subscribe(GameEvent.PLAYER_DIED, () => {
        console.log("[GameDirectorSystem] PLAYER_DIED event received!");
        if (this.gameState === "PLAYING" && this.activeCinematic === "NONE") {
          console.log("[GameDirectorSystem] Commencing PLAYER_DEATH cinematic...");
          this.activeCinematic = "PLAYER_DEATH";
          this.cinematicTimer = 0.0;
          this.maxCinematicSimTime = 0.6;
          GameDirectorSystem.timeScale = 0.2;

          const tethers = this.context.stores.get<TetherComponent>("tether");
          const pTether = tethers.get(this.context.refs.player);
          if (pTether) {
            pTether.isAttached = false;
            pTether.tension = 0.0;
          }

          this.context.broker.publish(GameEvent.CAMERA_SHAKE_TRIGGERED, {
            amplitude: 1.5,
            duration: 1.2
          });
        }
      })
    );

    this.unsubscribes.push(
      this.context.broker.subscribe(GameEvent.WEAVER_DIED, () => {
        console.log("[GameDirectorSystem] WEAVER_DIED event received!");
        if (this.gameState === "PLAYING" && this.activeCinematic === "NONE") {
          console.log("[GameDirectorSystem] Commencing WEAVER_DEATH cinematic...");
          this.activeCinematic = "WEAVER_DEATH";
          this.cinematicTimer = 0.0;
          this.maxCinematicSimTime = 0.875;
          GameDirectorSystem.timeScale = 0.25;

          this.context.broker.publish(GameEvent.CAMERA_SHAKE_TRIGGERED, {
            amplitude: 0.8,
            duration: 0.4
          });
        }
      })
    );

    this.unsubscribes.push(
      this.context.broker.subscribe(GameEvent.PLAYER_HEALTH_CHANGED, (payload) => {
        if (payload.hp === 1 && this.gameState === "PLAYING" && this.activeCinematic === "NONE") {
          console.log("[GameDirectorSystem] Player dropped to 1 HP! Triggering Adrenaline Surge slomo...");
          this.adrenalineTimer = this.ADRENALINE_SURGE_DURATION;
        }
      })
    );

    window.addEventListener("keydown", this.handleKeyDown);
  }

  private handleKeyDown = (e: KeyboardEvent): void => {
    if (e.key.toLowerCase() === "r" && this.gameState !== "PLAYING") {
      this.resetRequested = true;
    }

    if (
      e.key.toLowerCase() === "k" &&
      this.gameState === "PLAYING" &&
      this.activeCinematic === "NONE"
    ) {
      const healths = this.context.stores.get<HealthComponent>("health");
      const wHealth = healths.get(this.context.refs.weaver);
      if (wHealth && wHealth.current > 0) {
        wHealth.current = 0;
        this.context.broker.publish(GameEvent.WEAVER_DAMAGED, {
          amount: wHealth.max,
          source: "CHEAT_CODE"
        });
        this.context.broker.publish(GameEvent.WEAVER_HEALTH_CHANGED, {
          hp: 0,
          maxHp: wHealth.max
        });
      }
    }
  };

  public update(dt: number): void {
    if (this.resetRequested) {
      this.resetGame();
      this.resetRequested = false;
      return;
    }

    if (this.activeCinematic !== "NONE") {
      this.cinematicTimer += dt;
      console.log(`[GameDirectorSystem] Cinematic progress: ${this.cinematicTimer.toFixed(3)} / ${this.maxCinematicSimTime}`);
      if (this.cinematicTimer >= this.maxCinematicSimTime) {
        const finishedCinematic = this.activeCinematic;
        this.activeCinematic = "NONE";
        GameDirectorSystem.timeScale = 1.0;

        if (finishedCinematic === "PLAYER_DEATH") {
          console.log("[GameDirectorSystem] Player death cinematic complete! Publishing GAME_OVER event...");
          this.gameState = "GAME_OVER";
          this.context.broker.publish(GameEvent.GAME_OVER, undefined);
        } else if (finishedCinematic === "WEAVER_DEATH") {
          console.log("[GameDirectorSystem] Weaver death cinematic complete! Publishing GAME_WIN event...");
          this.gameState = "VICTORY";
          this.context.broker.publish(GameEvent.GAME_WIN, undefined);
        }
      }
    } else {
      if (this.adrenalineTimer > 0) {
        this.adrenalineTimer -= dt;
        const progress = Math.max(0, this.adrenalineTimer / this.ADRENALINE_SURGE_DURATION);
        GameDirectorSystem.timeScale = 0.45 + (1.0 - progress) * 0.55;
      } else {
        GameDirectorSystem.timeScale = 1.0;
      }
    }
  }

  private resetGame(): void {
    console.log("[GameDirectorSystem] Resetting game state...");
    this.gameState = "PLAYING";
    this.activeCinematic = "NONE";
    this.cinematicTimer = 0.0;
    this.adrenalineTimer = 0.0;
    GameDirectorSystem.timeScale = 1.0;

    this.spawner.spawnWeaver(this.context.refs.weaver);
    this.spawner.spawnPlayer(this.context.refs.player);

    this.context.broker.publish(GameEvent.GAME_RESET, undefined);

    const healths = this.context.stores.get<HealthComponent>("health");
    const pHealth = healths.get(this.context.refs.player);
    const wHealth = healths.get(this.context.refs.weaver);

    this.context.broker.publish(GameEvent.PLAYER_HEALTH_CHANGED, {
      hp: pHealth?.current || GAMEPLAY_TUNING.PLAYER.MAX_INTEGRITY,
      maxHp: pHealth?.max || GAMEPLAY_TUNING.PLAYER.MAX_INTEGRITY
    });
    this.context.broker.publish(GameEvent.WEAVER_STATE_CHANGE, {
      state: "PATROLLING",
      hue: this.HASH + VISUAL_JUICE_CONFIG.WEAVER_COLORS.SWEEPING
    });
    this.context.broker.publish(GameEvent.WEAVER_HEALTH_CHANGED, {
      hp: wHealth?.current || 100,
      maxHp: wHealth?.max || 100
    });
  }

  public dispose(): void {
    window.removeEventListener("keydown", this.handleKeyDown);
    this.unsubscribes.forEach((unsub) => unsub());
    this.unsubscribes = [];
  }
}

