:root {
  --bg-void: rgb(5, 5, 6);
  --bg-surface: rgb(14, 14, 17);
  --bg-elevated: rgb(22, 22, 26);
  --border-subtle: rgb(39, 39, 42);
  --border-strong: rgb(63, 63, 70);
  --text-main: rgb(244, 244, 245);
  --text-muted: rgb(161, 161, 170);
  --accent-tension: rgb(245, 158, 11);
  --accent-danger: rgb(239, 68, 68);
  --accent-success: rgb(16, 185, 129);

  /* Neomorphic Design Tokens */
  --void-bg: #07080b;
  --surface-bg: #0c0e12;
  --surface-elevated: #141820;
  --surface-highlight: #1d222d;
  --signal-green: #22c55e;
  --signal-green-glow: rgba(34, 197, 94, 0.45);
  --signal-red: #ef4444;
  --signal-red-glow: rgba(239, 68, 68, 0.45);
