        }}
        animate={{
          width: variant.bubbleSize,
          height: variant.bubbleSize,
          x: "-50%",
          y: "-50%",
        }}
        transition={{ type: "spring", stiffness: 180, damping: 15 }}
      >
        <AnimatePresence mode="wait">
          {cursorType === "text" && (
            <motion.div
              key="text-icon"
