              d="M22.917,13.375l51.333,51.333l-19.03,-3.781l14.863,23.031l-8.833,8.834l-14.863,-23.032l-4.387,27.198l-19.083,-83.583Z"
              fill={variant.color}
              stroke="rgba(0,0,0,0.5)"
              strokeWidth="3"
                />
              </svg>
            </motion.div>
          )}
        </div>
      );
    }

