import * as BABYLON from "@babylonjs/core";
import { ARENA_CONFIG } from "../../core/engine/ArenaConfig";
import { ProceduralTextureGenerator } from "../scene/ProceduralTextureGenerator";

export class ArenaGeometry {
  constructor(private scene: BABYLON.Scene) {}

  public generateElevatorShaft(): void {
    const textureGen = new ProceduralTextureGenerator();

    const wallMaterial = new BABYLON.PBRMaterial("wallMat", this.scene);
    wallMaterial.metallic = 0.0;
    wallMaterial.roughness = 0.85;
    wallMaterial.albedoColor = new BABYLON.Color3(0.043, 0.051, 0.063);

    textureGen.generatePBRTextures("concreteWall", this.scene, {
      resolution: 512,
      noiseScale: 10.0,
      bumpStrength: 2.5,
      baseColor: new BABYLON.Color3(0.043, 0.051, 0.063),
      roughnessMin: 0.75,
      roughnessMax: 0.98,
      metallic: 0.0
    }).then((wallTexs) => {
      wallMaterial.albedoTexture = wallTexs.albedo;
      wallMaterial.bumpTexture = wallTexs.normal;
      wallMaterial.metallicTexture = wallTexs.orm;
      wallMaterial.useAmbientOcclusionFromMetallicTextureRed = true;
      wallMaterial.useRoughnessFromMetallicTextureGreen = true;
      wallMaterial.useMetallnessFromMetallicTextureBlue = true;
      wallMaterial.useRoughnessFromMetallicTextureAlpha = false;
      wallMaterial.enableSpecularAntiAliasing = true;
      wallMaterial.forceIrradianceInFragment = true;
    });

    const panelMaterial = new BABYLON.PBRMaterial("panelMat", this.scene);
    panelMaterial.metallic = 0.25;
    panelMaterial.roughness = 0.65;
    panelMaterial.albedoColor = new BABYLON.Color3(0.08, 0.09, 0.11);

    textureGen.generatePBRTextures("scrollingPanel", this.scene, {
      resolution: 512,
      noiseScale: 16.0,
      bumpStrength: 1.8,
      baseColor: new BABYLON.Color3(0.08, 0.09, 0.11),
      roughnessMin: 0.45,
      roughnessMax: 0.75,
      metallic: 0.2
    }).then((panelTexs) => {
      panelMaterial.albedoTexture = panelTexs.albedo;
      panelMaterial.bumpTexture = panelTexs.normal;
      panelMaterial.metallicTexture = panelTexs.orm;
      panelMaterial.useAmbientOcclusionFromMetallicTextureRed = true;
      panelMaterial.useRoughnessFromMetallicTextureGreen = true;
      panelMaterial.useMetallnessFromMetallicTextureBlue = true;
      panelMaterial.useRoughnessFromMetallicTextureAlpha = false;
      panelMaterial.enableSpecularAntiAliasing = true;
      panelMaterial.forceIrradianceInFragment = true;
    });

    const verticalGrooveMaterial = new BABYLON.PBRMaterial("grooveMat", this.scene);
    verticalGrooveMaterial.albedoColor = new BABYLON.Color3(0.015, 0.015, 0.02);
    verticalGrooveMaterial.roughness = 0.98;
    verticalGrooveMaterial.metallic = 0.0;

    const wallThickness = 2.0;
    const wallHeight = ARENA_CONFIG.VERTICAL.WALL_GEOMETRY_HEIGHT;
    const wallX = ARENA_CONFIG.HORIZONTAL.WALL_GEOMETRY_X;

    const leftWall = BABYLON.MeshBuilder.CreateBox(
      "leftWall",
      { width: wallThickness, height: wallHeight, depth: 4 },
      this.scene
    );
    leftWall.position.set(-wallX, wallHeight * 0.1, 0);
    leftWall.material = wallMaterial;
    leftWall.receiveShadows = true;

    const rightWall = BABYLON.MeshBuilder.CreateBox(
      "rightWall",
      { width: wallThickness, height: wallHeight, depth: 4 },
      this.scene
    );
    rightWall.position.set(wallX, wallHeight * 0.1, 0);
    rightWall.material = wallMaterial;
    rightWall.receiveShadows = true;

    const leftGroove = BABYLON.MeshBuilder.CreateBox(
      "leftWallGroove",
      { width: 0.08, height: wallHeight, depth: 3.8 },
      this.scene
    );
    leftGroove.position.set(-wallX + wallThickness / 2 - 0.04, wallHeight * 0.1, 0.02);
    leftGroove.material = verticalGrooveMaterial;
    leftGroove.receiveShadows = false;

    const rightGroove = BABYLON.MeshBuilder.CreateBox(
      "rightWallGroove",
      { width: 0.08, height: wallHeight, depth: 3.8 },
      this.scene
    );
    rightGroove.position.set(wallX - wallThickness / 2 + 0.04, wallHeight * 0.1, 0.02);
    rightGroove.material = verticalGrooveMaterial;
    rightGroove.receiveShadows = false;

    const panelBase = BABYLON.MeshBuilder.CreateBox(
      "panelBase",
      { width: 1.0, height: 1.0, depth: 1.0 },
      this.scene
    );
    panelBase.material = panelMaterial;
    panelBase.isVisible = false;

    const ribBase = BABYLON.MeshBuilder.CreateBox(
      "ribBase",
      { width: 0.25, height: 1.0, depth: 1.0 },
      this.scene
    );
    ribBase.material = verticalGrooveMaterial;
    ribBase.isVisible = false;

    const panelCount = 20;
    const panelSpacing = wallHeight / panelCount;
    for (let i = 0; i < panelCount; i++) {
      const panelY = (i - panelCount / 2) * panelSpacing + (wallHeight * 0.1);

      const heightScale = 0.45 + Math.abs(Math.sin(i * 1.5)) * 0.45;
      const panelHeight = panelSpacing * heightScale;

      const widthScale = 0.8 + Math.abs(Math.cos(i * 2.1)) * 0.35;
      const panelWidth = 0.1 * widthScale;

      const depthScale = 0.7 + Math.abs(Math.sin(i * 3.3)) * 0.45;
      const panelDepth = 3.6 * depthScale;

      const lp = panelBase.createInstance(`leftPanel_${i}`);
      lp.position.set(-wallX + wallThickness / 2 - 0.02, panelY, 0);
      lp.scaling.set(panelWidth, panelHeight, panelDepth);
      lp.receiveShadows = true;
      lp.metadata = { type: "scrolling_panel", index: i, initialY: panelY };

      const rp = panelBase.createInstance(`rightPanel_${i}`);
      rp.position.set(wallX - wallThickness / 2 + 0.02, panelY, 0);
      rp.scaling.set(panelWidth, panelHeight, panelDepth);
      rp.receiveShadows = true;
      rp.metadata = { type: "scrolling_panel", index: i, initialY: panelY };
    }

    const ribCount = 10;
    const ribSpacing = wallHeight / ribCount;
    for (let i = 0; i < ribCount; i++) {
      const ribY = (i - ribCount / 2) * ribSpacing + (wallHeight * 0.1);

      const ribHeight = 0.18 + Math.abs(Math.sin(i * 1.9)) * 0.22;
      const ribDepth = 4.15;

      const leftRib = ribBase.createInstance(`leftRib_${i}`);
      leftRib.position.set(-wallX + wallThickness / 2, ribY, 0);
      leftRib.scaling.set(1.0, ribHeight, ribDepth);
      leftRib.receiveShadows = true;
      leftRib.metadata = { type: "scrolling_rib", index: i, initialY: ribY };

      const rightRib = ribBase.createInstance(`rightRib_${i}`);
      rightRib.position.set(wallX - wallThickness / 2, ribY, 0);
      rightRib.scaling.set(1.0, ribHeight, ribDepth);
      rightRib.receiveShadows = true;
      rightRib.metadata = { type: "scrolling_rib", index: i, initialY: ribY };
    }

    const tickMat = new BABYLON.PBRMaterial("tickMat", this.scene);
    tickMat.albedoColor = new BABYLON.Color3(0.1, 0.13, 0.16);
    tickMat.metallic = 0.3;
    tickMat.roughness = 0.4;
    tickMat.emissiveColor = new BABYLON.Color3(0.45, 0.65, 0.85);
    tickMat.emissiveIntensity = 1.1;

    const tickBase = BABYLON.MeshBuilder.CreateBox(
      "tickBase",
      { width: 0.2, height: 0.08, depth: 2.1 },
      this.scene
    );
    tickBase.material = tickMat;
    tickBase.isVisible = false;

    const tickCount = 70;
    const tickSpacing = 2.0;
    const initialYOffset = -56.0;
    const tickX = ARENA_CONFIG.HORIZONTAL.TICK_GEOMETRY_X;

    for (let i = 0; i < tickCount; i++) {
      const initialY = i * tickSpacing + initialYOffset;

      const leftTick = tickBase.createInstance(`leftTick_${i}`);
      leftTick.position.set(-tickX, initialY, 0);
      leftTick.metadata = { type: "scrolling_tick", index: i, initialY: initialY };

      const rightTick = tickBase.createInstance(`rightTick_${i}`);
      rightTick.position.set(tickX, initialY, 0);
      rightTick.metadata = { type: "scrolling_tick", index: i, initialY: initialY };
    }
  }
}

import * as BABYLON from "@babylonjs/core";
import { ProceduralTextureGenerator } from "../scene/ProceduralTextureGenerator";

export function decoratePlayerSilkVisual(
  scene: BABYLON.Scene,
  pMesh: BABYLON.Mesh,
  height: number,
  radius: number
): void {
  pMesh.isVisible = false;

  const childMeshes = pMesh.getChildMeshes();
  for (let i = 0; i < childMeshes.length; i++) {
    childMeshes[i].dispose();
  }

  scene.lights.forEach((light) => {
    const shadowGen = light.getShadowGenerator();
    if (shadowGen) {
      const concreteGen = shadowGen as unknown as { removeShadowCaster?: (mesh: BABYLON.AbstractMesh) => void };
      if (concreteGen && typeof concreteGen.removeShadowCaster === "function") {
        concreteGen.removeShadowCaster(pMesh);
      }
    }
  });

  const innerBody = BABYLON.MeshBuilder.CreateCapsule(
    "player_inner_body",
    {
      height: height * 0.75,
      radius: radius * 0.65,
      subdivisions: 3
    },
    scene
  );
  innerBody.position.set(0, 0, 0);
  const innerMat = new BABYLON.PBRMaterial("playerInnerMat", scene);
  innerMat.albedoColor = new BABYLON.Color3(0.08, 0.07, 0.1);
  innerMat.roughness = 0.85;
  innerMat.metallic = 0.1;
  innerBody.material = innerMat;
  innerBody.parent = pMesh;

  const cocoonShell = BABYLON.MeshBuilder.CreateCapsule(
    "player_cocoon_shell",
    {
      height: height * 0.95,
      radius: radius * 0.95,
      subdivisions: 3
    },
    scene
  );
  cocoonShell.position.set(0, 0, 0);

  const textureGen = new ProceduralTextureGenerator();

  const silkMat = new BABYLON.PBRMaterial("playerSilkMat", scene);
  silkMat.metallic = 0.0;
  silkMat.roughness = 0.85;
  silkMat.albedoColor = new BABYLON.Color3(0.93, 0.95, 0.96);

  textureGen.generatePBRTextures("silkFiber", scene, {
    resolution: 512,
    noiseScale: 40.0,
    bumpStrength: 3.2,
    baseColor: new BABYLON.Color3(0.93, 0.95, 0.96),
    roughnessMin: 0.72,
    roughnessMax: 0.98,
    metallic: 0.0
  }).then((silkTexs) => {
    silkMat.albedoTexture = silkTexs.albedo;
    silkMat.bumpTexture = silkTexs.normal;
    silkMat.metallicTexture = silkTexs.orm;
    silkMat.useAmbientOcclusionFromMetallicTextureRed = true;
    silkMat.useRoughnessFromMetallicTextureGreen = true;
    silkMat.useMetallnessFromMetallicTextureBlue = true;
    silkMat.useRoughnessFromMetallicTextureAlpha = false;
  });

  silkMat.sheen.isEnabled = true;
  silkMat.sheen.intensity = 0.8;
  silkMat.sheen.roughness = 0.45;
  silkMat.sheen.color = new BABYLON.Color3(0.98, 0.96, 0.9);
  silkMat.emissiveColor = new BABYLON.Color3(0.05, 0.05, 0.05);
  silkMat.enableSpecularAntiAliasing = true;
  silkMat.forceIrradianceInFragment = true;

  cocoonShell.material = silkMat;
  cocoonShell.parent = pMesh;

  const bandCount = 7;
  const bandMat = new BABYLON.PBRMaterial("playerBandMat", scene);
  bandMat.metallic = 0.05;
  bandMat.roughness = 0.9;
  bandMat.albedoColor = new BABYLON.Color3(0.85, 0.88, 0.9);

  textureGen.generatePBRTextures("silkBand", scene, {
    resolution: 256,
    noiseScale: 30.0,
    bumpStrength: 2.8,
    baseColor: new BABYLON.Color3(0.85, 0.88, 0.9),
    roughnessMin: 0.75,
    roughnessMax: 0.95,
    metallic: 0.0
  }).then((bandTexs) => {
    bandMat.albedoTexture = bandTexs.albedo;
    bandMat.bumpTexture = bandTexs.normal;
    bandMat.metallicTexture = bandTexs.orm;
    bandMat.useAmbientOcclusionFromMetallicTextureRed = true;
    bandMat.useRoughnessFromMetallicTextureGreen = true;
    bandMat.useMetallnessFromMetallicTextureBlue = true;
    bandMat.useRoughnessFromMetallicTextureAlpha = false;
  });

  bandMat.sheen.isEnabled = true;
  bandMat.sheen.intensity = 0.6;
  bandMat.enableSpecularAntiAliasing = true;
  bandMat.forceIrradianceInFragment = true;

  for (let i = 0; i < bandCount; i++) {
    const t = i / (bandCount - 1);
    const bandY = (t - 0.5) * height * 0.75;
    const bandRadius = radius * (1.02 + Math.sin(t * Math.PI) * 0.06);

    const band = BABYLON.MeshBuilder.CreateTorus(
      `player_band_${i}`,
      {
        diameter: bandRadius * 2.0,
        thickness: radius * 0.16,
        tessellation: 10
      },
      scene
    );

    band.position.set(0, bandY, 0);
    band.rotation.x = 0.15 + Math.sin(i * 1.7) * 0.15;
    band.rotation.y = Math.cos(i * 2.3) * 0.25;
    band.rotation.z = Math.sin(i * 3.1) * 0.15;
    band.material = bandMat;
    band.parent = pMesh;
  }

  const tailPoints = [
    new BABYLON.Vector3(0, height * 0.45, 0),
    new BABYLON.Vector3(0.05, height * 0.55, -radius * 0.2),
    new BABYLON.Vector3(-0.08, height * 0.7, -radius * 0.5)
  ];
  const tail = BABYLON.MeshBuilder.CreateTube(
    "player_thread_tail",
    {
      path: tailPoints,
      radius: 0.035,
      tessellation: 6,
      cap: BABYLON.Mesh.CAP_ALL,
      updatable: false
    },
    scene
  );
  tail.material = silkMat;
  tail.parent = pMesh;

  pMesh.getChildMeshes().forEach((mesh) => {
    mesh.receiveShadows = true;
  });
}

src/visual/mesh/WeaverVisualFactory.ts:
import * as BABYLON from "@babylonjs/core";
import { RasterShearPlugin } from "../lighting/RasterShearPlugin";
import { ProceduralTextureGenerator } from "../scene/ProceduralTextureGenerator";

interface CustomPBRMaterial extends BABYLON.PBRMaterial {
  _shearPlugin?: RasterShearPlugin;
}

export function decorateWeaverVisual(
  scene: BABYLON.Scene,
  wMesh: BABYLON.Mesh,
  radius: number,
  registerShadowCaster?: (mesh: BABYLON.AbstractMesh) => void
): void {
  wMesh.isVisible = false;

  const childMeshes = wMesh.getChildMeshes();
  for (let i = 0; i < childMeshes.length; i++) {
    childMeshes[i].dispose();
  }

  scene.lights.forEach((light) => {
    const shadowGen = light.getShadowGenerator();
    if (shadowGen) {
      const concreteGen = shadowGen as unknown as { removeShadowCaster?: (mesh: BABYLON.AbstractMesh) => void };
      if (concreteGen && typeof concreteGen.removeShadowCaster === "function") {
        concreteGen.removeShadowCaster(wMesh);
      }
    }
  });

  const textureGen = new ProceduralTextureGenerator();

  const carapaceMat = new BABYLON.PBRMaterial("carapaceMat", scene) as CustomPBRMaterial;
  carapaceMat.metallic = 0.45;
  carapaceMat.roughness = 0.65;
  carapaceMat.albedoColor = new BABYLON.Color3(0.09, 0.07, 0.11);

  textureGen.generatePBRTextures("carapaceShell", scene, {
    resolution: 512,
    noiseScale: 28.0,
    bumpStrength: 2.2,
    baseColor: new BABYLON.Color3(0.09, 0.07, 0.11),
    roughnessMin: 0.55,
    roughnessMax: 0.85,
    metallic: 0.4
  }).then((carapaceTexs) => {
    carapaceMat.albedoTexture = carapaceTexs.albedo;
    carapaceMat.bumpTexture = carapaceTexs.normal;
    carapaceMat.metallicTexture = carapaceTexs.orm;
    carapaceMat.useAmbientOcclusionFromMetallicTextureRed = true;
    carapaceMat.useRoughnessFromMetallicTextureGreen = true;
    carapaceMat.useMetallnessFromMetallicTextureBlue = true;
    carapaceMat.useRoughnessFromMetallicTextureAlpha = false;
  });

  carapaceMat.clearCoat.isEnabled = true;
  carapaceMat.clearCoat.intensity = 0.35;
  carapaceMat.clearCoat.roughness = 0.4;
  carapaceMat.enableSpecularAntiAliasing = true;
  carapaceMat.forceIrradianceInFragment = true;

  const shearPluginCarapace = new RasterShearPlugin(carapaceMat);
  carapaceMat._shearPlugin = shearPluginCarapace;

  const shellMat = new BABYLON.PBRMaterial("carapaceUpperMat", scene) as CustomPBRMaterial;
  shellMat.metallic = 0.4;
  shellMat.roughness = 0.7;
  shellMat.albedoColor = new BABYLON.Color3(0.13, 0.09, 0.18);

  textureGen.generatePBRTextures("carapaceUpper", scene, {
    resolution: 512,
    noiseScale: 22.0,
    bumpStrength: 2.4,
    baseColor: new BABYLON.Color3(0.13, 0.09, 0.18),
    roughnessMin: 0.58,
    roughnessMax: 0.88,
    metallic: 0.35
  }).then((shellTexs) => {
    shellMat.albedoTexture = shellTexs.albedo;
    shellMat.bumpTexture = shellTexs.normal;
    shellMat.metallicTexture = shellTexs.orm;
    shellMat.useAmbientOcclusionFromMetallicTextureRed = true;
    shellMat.useRoughnessFromMetallicTextureGreen = true;
    shellMat.useMetallnessFromMetallicTextureBlue = true;
    shellMat.useRoughnessFromMetallicTextureAlpha = false;
  });

  shellMat.clearCoat.isEnabled = true;
  shellMat.clearCoat.intensity = 0.35;
  shellMat.clearCoat.roughness = 0.45;
  shellMat.enableSpecularAntiAliasing = true;
  shellMat.forceIrradianceInFragment = true;

  const shearPluginShell = new RasterShearPlugin(shellMat);
  shellMat._shearPlugin = shearPluginShell;

  const legMat = new BABYLON.PBRMaterial("legMat", scene) as CustomPBRMaterial;
  legMat.metallic = 0.3;
  legMat.roughness = 0.75;
  legMat.albedoColor = new BABYLON.Color3(0.04, 0.03, 0.05);

  textureGen.generatePBRTextures("legScratches", scene, {
    resolution: 256,
    noiseScale: 34.0,
    bumpStrength: 2.0,
    baseColor: new BABYLON.Color3(0.04, 0.03, 0.05),
    roughnessMin: 0.6,
    roughnessMax: 0.9,
    metallic: 0.25
  }).then((legTexs) => {
    legMat.albedoTexture = legTexs.albedo;
    legMat.bumpTexture = legTexs.normal;
    legMat.metallicTexture = legTexs.orm;
    legMat.useAmbientOcclusionFromMetallicTextureRed = true;
    legMat.useRoughnessFromMetallicTextureGreen = true;
    legMat.useMetallnessFromMetallicTextureBlue = true;
    legMat.useRoughnessFromMetallicTextureAlpha = false;
  });
  legMat.enableSpecularAntiAliasing = true;
  legMat.forceIrradianceInFragment = true;

  const shearPluginLeg = new RasterShearPlugin(legMat);
  legMat._shearPlugin = shearPluginLeg;

  const eyeMat = new BABYLON.StandardMaterial("weaverEyeMat", scene);
  eyeMat.emissiveColor = new BABYLON.Color3(1.0, 0.18, 0.31);
  eyeMat.disableLighting = true;

  const abdomen = BABYLON.MeshBuilder.CreateSphere(
    "weaver_abdomen",
    { diameterX: radius * 1.1, diameterY: radius * 1.5, diameterZ: radius * 1.1, segments: 16 },
    scene
  );
  abdomen.position.set(0, -radius * 0.3, radius * 0.1);
  abdomen.material = shellMat;
  abdomen.parent = wMesh;

  const positions = abdomen.getVerticesData(BABYLON.VertexBuffer.PositionKind);
  const halfY = radius * 0.75;
  if (positions) {
    for (let i = 0; i < positions.length; i += 3) {
      const x = positions[i];
      const y = positions[i + 1];
      const z = positions[i + 2];

      if (y < 0) {
        const normY = y / halfY;
        const r_sphere = Math.sqrt(Math.max(0, 1.0 - normY * normY));
        if (r_sphere > 0.001) {
          const r_cone = 1.0 + normY;
          const scaleFactor = r_cone / r_sphere;
          positions[i] = x * scaleFactor;
          positions[i + 2] = z * scaleFactor;
        } else {
          positions[i] = 0;
          positions[i + 2] = 0;
        }
      }
    }
    abdomen.setVerticesData(BABYLON.VertexBuffer.PositionKind, positions);
    const normals: number[] = [];
    const indices = abdomen.getIndices();
    if (indices) {
      BABYLON.VertexData.ComputeNormals(positions, indices, normals);
      abdomen.setVerticesData(BABYLON.VertexBuffer.NormalKind, normals);
    }
  }

  const head = BABYLON.MeshBuilder.CreateSphere(
    "weaver_head",
    { diameterX: radius * 0.9, diameterY: radius * 0.6, diameterZ: radius * 0.8 },
    scene
  );
  head.position.set(0, radius * 0.4, -radius * 0.1);
  head.material = carapaceMat;
  head.parent = wMesh;

  const eyeOffsets = [
    { x: -0.18, y: -0.15, z: -0.32 },
    { x: 0.18, y: -0.15, z: -0.32 },
    { x: -0.08, y: -0.05, z: -0.38 },
    { x: 0.08, y: -0.05, z: -0.38 },
    { x: -0.25, y: -0.05, z: -0.28 },
    { x: 0.25, y: -0.05, z: -0.28 }
  ];
  eyeOffsets.forEach((offset, idx) => {
    const eye = BABYLON.MeshBuilder.CreateSphere(
      `weaver_eye_${idx}`,
      { diameter: radius * 0.12 },
      scene
    );
    eye.position.set(offset.x * radius, offset.y * radius, offset.z * radius);
    eye.material = eyeMat;
    eye.parent = head;
  });

  for (let side = 0; side < 2; side++) {
    const sideSign = side === 0 ? -1 : 1;
    for (let l = 0; l < 4; l++) {
      const legRoot = new BABYLON.TransformNode(`leg_root_${sideSign}_${l}`, scene);
      legRoot.parent = wMesh;

      const angleOffset = (l - 1.5) * 0.45;
      const basePosX = sideSign * radius * 0.45;
      const basePosY = radius * 0.1 + (l - 1.5) * 0.15 * radius;
      const basePosZ = (l - 1.5) * 0.25 * radius;
      legRoot.position.set(basePosX, basePosY, basePosZ);

      const coxaLength = radius * 0.65;
      const coxa = BABYLON.MeshBuilder.CreateCylinder(
        `coxa_${sideSign}_${l}`,
        {
          height: coxaLength,
          diameterTop: radius * 0.14,
          diameterBottom: radius * 0.18,
          tessellation: 6
        },
        scene
      );
      coxa.position.set(sideSign * coxaLength * 0.45, coxaLength * 0.1, -coxaLength * 0.1);
      coxa.rotation.y = angleOffset;
      coxa.rotation.z = sideSign * (Math.PI / 4 + angleOffset * 0.3);
      coxa.material = carapaceMat;
      coxa.parent = legRoot;

      const tibiaLength = radius * 0.9;
      const tibia = BABYLON.MeshBuilder.CreateCylinder(
        `tibia_${sideSign}_${l}`,
        {
          height: tibiaLength,
          diameterTop: radius * 0.04,
          diameterBottom: radius * 0.12,
          tessellation: 6
        },
        scene
      );
      tibia.position.set(sideSign * tibiaLength * 0.35, -tibiaLength * 0.4, 0);
      tibia.rotation.z = -sideSign * (Math.PI / 3);
      tibia.material = legMat;
      tibia.parent = coxa;
    }
  }

  wMesh.getChildMeshes().forEach((mesh) => {
    if (mesh.name.includes("weaver_eye") || mesh.name.includes("spinneret_glow")) {
      mesh.receiveShadows = false;
    } else {
      mesh.receiveShadows = true;
      if (registerShadowCaster) {
        registerShadowCaster(mesh);
      }
    }
  });
}

